<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=html_escape($title);?></title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@3.34.1/dist/tabler-icons.min.css"><style>body{background:linear-gradient(135deg,#eef6ff,#faf5ff);min-height:100vh}.reset-wrap{max-width:620px;margin:auto;padding:48px 16px}.reset-card{border:0;border-radius:22px;box-shadow:0 20px 55px #23387618}.reset-icon{width:64px;height:64px;display:grid;place-items:center;border-radius:20px;background:#ede9fe;color:#6d28d9;font-size:2rem}.secret{font:800 1.45rem ui-monospace,monospace;letter-spacing:.08em;background:#f8fafc;border:1px dashed #94a3b8;border-radius:14px;padding:14px;text-align:center}</style></head><body><main class="reset-wrap"><a href="<?=base_url('login');?>" class="btn btn-link mb-2">← Kembali ke login</a><section class="card reset-card"><div class="card-body p-4 p-md-5"><div class="reset-icon mb-3"><i class="ti ti-key"></i></div><h1 class="h2"><?=html_escape($heading);?></h1><p class="text-secondary"><?=html_escape($intro);?></p><?php if(!empty($error)):?><div class="alert alert-danger"><?=html_escape($error);?></div><?php endif;?><?php if(!empty($success)):?><div class="alert alert-success"><?=html_escape($success);?></div><?php endif;?>
<?php if($mode==='request'):?><?=form_open('auth/submit_password_reset');?><div class="mb-3"><label class="form-label">Username, NIK, email, atau nomor anggota</label><input class="form-control form-control-lg" name="identifier" required maxlength="180" autocomplete="username"></div><div class="mb-3"><label class="form-label">Nomor WhatsApp yang terdaftar</label><input class="form-control form-control-lg" name="phone" required maxlength="32" inputmode="tel" placeholder="08xxxxxxxxxx"></div><button class="btn btn-primary btn-lg w-100"><i class="ti ti-brand-whatsapp me-1"></i>Kirim Tautan Reset lewat WhatsApp</button><?=form_close();?><div class="alert alert-info mt-3 mb-0"><i class="ti ti-shield-lock me-1"></i>Password lama tidak berubah sampai Anda membuka tautan WhatsApp dan membuat password baru.</div><div class="text-center mt-3"><a href="<?=base_url('auth/password_reset_status');?>">Sudah meminta reset? Cek status</a></div>
<?php elseif($mode==='lookup'):?><?=form_open('auth/password_reset_status');?><div class="mb-3"><label class="form-label">Kode permintaan reset</label><input class="form-control" name="request_code" required placeholder="RST-..."></div><div class="mb-3"><label class="form-label">Nomor WhatsApp terdaftar</label><input class="form-control" name="phone" required inputmode="tel"></div><button class="btn btn-primary w-100"><i class="ti ti-search me-1"></i>Cek Status Reset</button><?=form_close();?>
<?php elseif($mode==='set_password'&&$row&&!$row['is_expired']&&!$row['is_completed']):?><?=form_open('auth/complete_password_reset');?><input type="hidden" name="token" value="<?=html_escape($reset_token);?>"><div class="mb-3"><label class="form-label">Password baru</label><input type="password" class="form-control form-control-lg" name="password" required minlength="8" maxlength="72" autocomplete="new-password"></div><div class="mb-3"><label class="form-label">Ulangi password baru</label><input type="password" class="form-control form-control-lg" name="password_confirmation" required minlength="8" maxlength="72" autocomplete="new-password"></div><button class="btn btn-primary btn-lg w-100"><i class="ti ti-lock-check me-1"></i>Simpan Password Baru</button><?=form_close();?>
<?php endif;?><?php if($row&&$mode==='result'):?><?php $approval=$row['approval_status']??'pending';$statusText=['pending'=>'Menunggu Verifikasi','approved'=>'Disetujui','rejected'=>'Ditolak','wa_sent'=>'Tautan WA Dikirim'][$approval]??'Diproses';$statusColor=['pending'=>'yellow','approved'=>'green','rejected'=>'red','wa_sent'=>'blue'][$approval]??'secondary';?><hr class="my-4"><div class="d-flex justify-content-between"><strong><?=html_escape($row['request_code']);?></strong><span class="badge bg-<?=$statusColor;?>-lt"><?=html_escape($statusText);?></span></div><p class="mt-3 mb-2"><?=html_escape($delivery[$row['delivery_status']]??'Permintaan sedang diproses.');?></p><?php if($approval==='approved'&&!empty($row['approved_password'])):?><label class="form-label mt-3">Password baru hasil verifikasi</label><div class="secret"><?=html_escape($row['approved_password']);?></div><div class="alert alert-warning mt-3 mb-0">Gunakan password ini untuk masuk, lalu segera ubah menjadi password pribadi melalui halaman akun. Password hanya ditampilkan selama 24 jam.</div><?php elseif($approval==='rejected'):?><div class="alert alert-danger mt-3 mb-0">Permintaan belum dapat disetujui. <?=html_escape($row['review_note']??'Silakan hubungi petugas untuk verifikasi lebih lanjut.');?></div><?php elseif($approval==='pending'):?><div class="alert alert-info mt-3 mb-0"><i class="ti ti-clock me-1"></i>Petugas sedang memverifikasi permintaan. Cek kembali halaman ini secara berkala menggunakan kode dan nomor WhatsApp terdaftar.</div><?php else:?><div class="alert alert-info mt-3 mb-0"><i class="ti ti-shield-check me-1"></i>Demi keamanan, tautan reset hanya dikirim ke nomor WhatsApp terdaftar dan tidak ditampilkan pada halaman status.</div><?php endif;?><?php endif;?></div></section></main></body></html>
